bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const client=createCreatorTelegramFetch();
try{
 const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
 const result=await client.fetch('https://api.telegram.org/bot'+token+'/getChatAdministrators',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({chat_id:-1002373696859}),signal:AbortSignal.timeout(20000)});
 const body=await result.json();
 if(body?.ok!==true||!Array.isArray(body.result))process.exitCode=61;
 else if(body.result.some(x=>x?.user?.id===788044853))process.exitCode=71;
 else process.exitCode=72;
}catch{process.exitCode=79}finally{await client.close()}
JS
